def minimize_xor_with_bit_count(num1,num2):
    needed=num2.bit_count();answer=0
    for bit in range(31,-1,-1):
        if needed and num1>>bit&1:answer|=1<<bit;needed-=1
    for bit in range(32):
        if needed and not answer>>bit&1:answer|=1<<bit;needed-=1
    return answer

